$terminalBefore=TerminalSnapshot;AssertTerminalSnapshot $terminalBefore
if(-not(Test-Path $evidence)){New-Item -ItemType Directory -Path $evidence|Out-Null}
$roots=@($install,$state,(Join-Path $state 'Activations'),(Join-Path $state 'Authorizations'),(Join-Path $state 'Config'),(Join-Path $state 'Config\BuildInputClosures'),(Join-Path $state 'Config\SourceInputs'),(Join-Path $state 'Evidence'),(Join-Path $state 'Ledger'),(Join-Path $state 'Objects'),(Join-Path $state 'Recovery'),(Join-Path $state 'Responses'),(Join-Path $state 'Staging'),(Join-Path $state 'Trust'))
foreach($root in $roots){if(-not(Test-Path -LiteralPath $root)){New-Item -ItemType Directory -Path $root|Out-Null}}
foreach($root in @($install,$state)){Run $icacls @($root,'/setowner','SYSTEM','/T','/C');Run $icacls @($root,'/inheritance:r','/grant:r','SYSTEM:(OI)(CI)(F)','BUILTIN\Administrators:(OI)(CI)(F)',"$account`:(OI)(CI)(RX)","$terminal`:(OI)(CI)(RX)",'BUILTIN\Users:(OI)(CI)(RX)','/T','/C')}
$mutable=@('Activations','Authorizations','Evidence','Ledger','Objects','Recovery','Responses')|ForEach-Object{Join-Path $state $_}
foreach($root in $mutable){Run $icacls @($root,'/inheritance:r','/grant:r','SYSTEM:(OI)(CI)(F)','BUILTIN\Administrators:(OI)(CI)(F)',"$account`:(OI)(CI)(F)","$terminal`:(OI)(CI)(RX)",'BUILTIN\Users:(OI)(CI)(RX)','/T','/C')}
$stageRoot=Join-Path (Join-Path $state 'Staging') $nonce;if(Test-Path $stageRoot){throw 'Transition staging root already exists'};New-Item -ItemType Directory -Path $stageRoot|Out-Null
foreach($item in Get-ChildItem -LiteralPath (Join-Path $build 'TargetStaging') -Force){Copy-Item -LiteralPath $item.FullName -Destination $stageRoot -Recurse}
Run $icacls @($stageRoot,'/setowner','SYSTEM','/T','/C');Run $icacls @($stageRoot,'/inheritance:r','/grant:r','SYSTEM:(OI)(CI)(F)','BUILTIN\Administrators:(OI)(CI)(F)',"$account`:(OI)(CI)(RX)",'BUILTIN\Users:(OI)(CI)(RX)','/T','/C')
$installInput=Join-Path $build 'Install'
CopyNew (Join-Path $installInput 'RandleTerminalUpgradeAuthority.exe') (Join-Path $install 'RandleTerminalUpgradeAuthority.exe');CopyNew (Join-Path $installInput 'RandleTerminalUpgradeClient.exe') (Join-Path $install 'RandleTerminalUpgradeClient.exe');CopyNew (Join-Path $installInput 'RandleTerminalUpgradeProtocolProbe.exe') (Join-Path $install 'RandleTerminalUpgradeProtocolProbe.exe');CopyNew (Join-Path $installInput 'RandleTerminalUpgradePublicVerifier.exe') (Join-Path $install 'RandleTerminalUpgradePublicVerifier.exe')
CopyNew (Join-Path $installInput 'unit2_upgrade_policy.json') (Join-Path $state 'Config\upgrade_authority_policy.json');CopyNew (Join-Path $installInput 'dependency_manifest.json') (Join-Path $state 'Config\dependency_manifest.json');CopyNew (Join-Path $installInput 'unit2_build_receipt.json') (Join-Path $state 'Config\upgrade_authority_build_receipt.json')
$certTarget=Join-Path $state 'Trust\upgrade_authority_public.cer';if((Hash (Join-Path $installInput 'upgrade_authority_public.cer')) -cne (Hash $certTarget)){throw 'Public certificate differs from bootstrap'}
foreach($root in @($install,(Join-Path $state 'Config'),(Join-Path $state 'Trust'))){Run $icacls @($root,'/setowner','SYSTEM','/T','/C');Run $icacls @($root,'/inheritance:r','/grant:r','SYSTEM:(OI)(CI)(F)','BUILTIN\Administrators:(OI)(CI)(F)',"$account`:(OI)(CI)(RX)","$terminal`:(OI)(CI)(RX)",'BUILTIN\Users:(OI)(CI)(RX)','/T','/C')}
$boundaryPath=Join-Path $evidence 'prestart_service_boundary.json';& (Join-Path $install 'RandleTerminalUpgradePublicVerifier.exe') apply-boundary $boundaryPath;if($LASTEXITCODE -ne 0){throw 'Prestart service boundary enforcement failed'}
Run $sc @('start',$service)
$deadline=[DateTime]::UtcNow.AddSeconds(30);do{$svc=Get-Service -Name $service;if($svc.Status -eq 'Running'){break};Start-Sleep -Milliseconds 250}while([DateTime]::UtcNow -lt $deadline);if($svc.Status -ne 'Running'){throw 'Upgrade service failed to start'}
$terminalAfter=TerminalSnapshot;AssertTerminalSnapshot $terminalAfter;if([int64]$terminalBefore.process_id -ne [int64]$terminalAfter.process_id){throw 'Existing terminal service process changed'}
