$record=[ordered]@{artifact_type='R7_UNIT2_UPGRADE_AUTHORITY_COMPLETION_RECORD';build_manifest_sha256=(Hash (Join-Path $build 'unit2_build_manifest.json'));existing_terminal_after=$terminalAfter;existing_terminal_before=$terminalBefore;installed_files=$installed;preflight_baseline_sha256=$preflightSha;schema_version='1.0.0';service_name=$service;service_sid=$sid;source_commit=$SourceCommit;staging_root=$stageRoot;status='PASS';terminal_installation_performed=$false;utilities=@([ordered]@{role=[string]$scRow.role;sha256=[string]$scRow.measurement.sha256},[ordered]@{role=[string]$icaclsRow.role;sha256=[string]$icaclsRow.measurement.sha256},[ordered]@{role=[string]$powershellRow.role;sha256=[string]$powershellRow.measurement.sha256})}
$recordPath=Join-Path $evidence 'unit2_completion_record.json';[IO.File]::WriteAllText($recordPath,($record|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));Get-FileHash -LiteralPath $recordPath -Algorithm SHA256
